var Game2048=(function($){const app=$ui.getAjax();const SIZE=4;const DIRS={up:[-1,0],right:[0,1],down:[1,0],left:[0,-1]};const KEYS={ArrowUp:"up",ArrowRight:"right",ArrowDown:"down",ArrowLeft:"left"};let ctn,grid,size=SIZE,board=[],score=0,max=0,nextWin=2048,best=0,simu=null,freeze=false,startX=0,startY=0,cellWidth=0,cellMargin=0,boardWidth=0;async function install(){await $factory.loadCSS({url:app.getResourceURL("SIM_2048_STYLES","CSS")});startGame();}
function startGame(){let saved=app.sysparams.GAME_2048;const begin=c=>{if(saved==="empty")
saved=null;try{saved=JSON.parse(saved);}
catch{}
newGame(c,saved);};const end=()=>{app.setSysParam("GAME_2048",getData(),true);$(document).off("keydown",onKeyDown);};const area=$view.splitter.isEnabled()&&$view.splitter.request({name:"game2048",title:"2048",position:"right"});if(area){$ui.contentUnload(area);const c=$('<div class="js-content-unload"/>').css("max-width",360).on("ui.content.unload",end);area.empty().append(c);begin(c);return;}
const width=Math.min($(window).width()||300,300);const c=$('<div/>').width(width-35);$tools.dialog({name:"game2048",content:c,width,slide:"right",onload(){begin(c);},unload:end});}
function newGame(c,data){data=data||{};size=data.size||SIZE;score=data.score||0;board=data.board||[];if(data.best)best=data.best;simu=null;display(c);if(!data.board){newNumber();newNumber();}
updateBoard();ctn.attr("tabindex","1").trigger("focus");nextWin=Math.max(2048,boardMax());freeze=false;$(document).off("keydown",onKeyDown).on("keydown",onKeyDown);ctn.off("touchstart",onTouchStart).on("touchstart",onTouchStart);ctn.off("touchend",onTouchEnd).on("touchend",onTouchEnd);isGameOver();}
function getData(){return{size,score,best,board};}
function play(e,dir){if(!dir)
return;e.preventDefault();e.stopPropagation();const m=move(dir);setTimeout(()=>next(m),150);}
function onKeyDown(e){!freeze&&play(e,KEYS[e.key]);}
function onTouchStart(e){if(freeze)
return;e.preventDefault();e.stopPropagation();startX=e.touches[0].pageX;startY=e.touches[0].pageY;}
function onTouchEnd(e){if(freeze)
return;const dx=e.changedTouches[0].pageX-startX,dy=e.changedTouches[0].pageY-startY;if(Math.abs(dx)<100&&Math.abs(dy)<100)
return;play(e,Math.abs(dx)>Math.abs(dy)?(dx>0?"right":"left"):(dy>0?"down":"up"));}
function next(m){updateBoard();if(m){isGameWin();m.score&&updateScore(m.score);newNumber();}
isGameOver();}
function display(c){if(c)boardWidth=c.width();cellWidth=boardWidth/(size*1.15+0.15);cellMargin=cellWidth*0.15;ctn=$('.game-2048').empty();if(!ctn.length)
ctn=$('<div class="game-2048"/>');c?.html(ctn);$('<div class="header"/>').append($('<div class="title"/>').text("2048")).append($('<div class="score" id="score"/>').text(formatScore(score))).append($('<div class="score best" id="best"/>').text(formatScore(best))).appendTo(ctn);$('<div class="header"/>').append($('<a href="#"/>').text("Retry").on("click",retry)).append($('<a href="#"/>').text("Autorun").on("click",autorun)).appendTo(ctn);grid=$('<div class="grid"/>').appendTo(ctn).css({width:boardWidth,height:boardWidth});for(let i=0;i<size;i++){board[i]||=[];for(let j=0;j<size;j++){board[i][j]||=0;$('<div class="cell"/>').attr("id",`c-${i}-${j}`).css({width:cellWidth,height:cellWidth,top:pos(i),left:pos(j)}).appendTo(grid);}}
$('<a href="https://fr.wikipedia.org/wiki/2048_(jeu_vid%C3%A9o)" target="_blank"/>').text("About").appendTo(ctn);}
function updateBoard(){max=0;$(".cell-num",grid).remove();for(let i=0;i<size;i++){for(let j=0;j<size;j++){const n=board[i][j];if(n>max)
max=n;$('<div class="cell-num"/>').attr("id",`cn-${i}-${j}`).addClass(n?`num-${n}`:"").css({width:n?cellWidth:0,height:n?cellWidth:0,top:pos(i)+(n?0:cellWidth/2),left:pos(j)+(n?0:cellWidth/2),"line-height":`${cellWidth}px`,"font-size":fontSize(n)}).text(n||"").appendTo(grid);}}}
function showNumber(i,j,n){$(`#cn-${i}-${j}`,grid).addClass(`num-${n}`).text(n).animate({width:cellWidth,height:cellWidth,top:pos(i),left:pos(j)},100);}
function moveNumber(x,y,a,b){$(`#cn-${x}-${y}`,grid).animate({top:pos(a),left:pos(b)},100);}
const pos=i=>cellMargin+i*(cellWidth+cellMargin);const formatScore=n=>n>1000?`${Math.round(n / 100) / 10}k`:n;const fontSize=n=>`${(n < 100 ? 0.55 : n < 1000 ? 0.45 : 0.35) * cellWidth}px`;function updateScore(inc,only){if(inc)score+=inc;$("#score",ctn).text(formatScore(score));if(!only&&score>best){best=score;$("#best",ctn).text(formatScore(best));}}
function popup(text,btn){closePopup();freeze=true;$('<div class="popup"/>').append($('<p/>').text(text)).append($('<div class="lower"/>').append(btn)).appendTo(grid);}
function closePopup(){$(".popup",grid).remove();freeze=false;}
function retry(e){e?.preventDefault();e?.stopPropagation();closePopup();newGame();}
function isGameOver(){if(isFull()&&!canMove())
gameOver();}
function gameOver(){updateBoard();popup("Game over!",$('<button class="btn retry-button"/>').text("Try again!").on("click",retry));}
function isGameWin(){if(max>=nextWin)
gameWin();}
function gameWin(){updateBoard();nextWin*=2;popup("You win!",$('<button class="btn retry-button"/>').text(`Continue to ${nextWin}!`).on("click",closePopup));}
const isFull=()=>!board.flat().includes(0);const boardMax=()=>Math.max(0,...board.flat());function newNumber(){const empty=[];for(let i=0;i<size;i++)
for(let j=0;j<size;j++)
if(board[i][j]===0)
empty.push([i,j]);if(!empty.length)
return false;const[x,y]=empty[Math.floor(Math.random()*empty.length)];const n=Math.random()<0.9?2:4;board[x][y]=n;!simu&&showNumber(x,y,n);return true;}
function move(dir){if(!canMoveDir(DIRS[dir]))
return;const horizontal=dir==="left"||dir==="right";const forward=dir==="right"||dir==="down";const at=(line,p)=>horizontal?board[line][p]:board[p][line];const put=(line,p,v)=>{if(horizontal)board[line][p]=v;else board[p][line]=v;};const animate=(line,from,to)=>horizontal?moveNumber(line,from,line,to):moveNumber(from,line,to,line);let score=0;for(let line=0;line<size;line++){const order=Array.from({length:size},(_,i)=>forward?size-1-i:i);const tiles=order.filter(p=>at(line,p));const result=[];for(let t=0;t<tiles.length;t++){const v=at(line,tiles[t]);if(t+1<tiles.length&&at(line,tiles[t+1])===v){result.push({v:v+v,from:[tiles[t],tiles[t+1]]});score+=v+v;t++;}
else
result.push({v,from:[tiles[t]]});}
order.forEach((p,i)=>{const cell=result[i];put(line,p,cell?cell.v:0);if(cell&&!simu)
cell.from.forEach(src=>src!==p&&animate(line,src,p));});}
return{score};}
function canMoveDir([dr,dc]){for(let i=0;i<size;i++)
for(let j=0;j<size;j++){const v=board[i][j];if(!v)
continue;const ni=i+dr,nj=j+dc;if(ni<0||ni>=size||nj<0||nj>=size)
continue;if(board[ni][nj]===0||board[ni][nj]===v)
return true;}
return false;}
const canMove=()=>Object.values(DIRS).some(canMoveDir);function autorun(e){e?.preventDefault();e?.stopPropagation();const btn=e?$(e.currentTarget):null;if(btn?.hasClass("on")){btn.removeClass("on").text("Autorun");freeze=false;simu=null;return;}
if(btn){btn.addClass("on").text("Stop");simu=freeze=true;}
if(!simu||!canMove())
return;const pick=ai();simu=false;if(!pick.move)
return;const m=move(pick.move);setTimeout(()=>{updateBoard();if(m.score)updateScore(m.score,1);newNumber();if(simu===false){simu=true;autorun();}},150);}
function ai(){const RUNS=200;const names=Object.keys(DIRS);const snapshot=board;const clone=()=>{board=snapshot.map(row=>row.slice());};const run=dir=>{clone();let m=move(dir);if(!m)return-1;newNumber();let s=m.score;while(canMove()){m=move(names[Math.floor(Math.random()*4)]);if(m){s+=m.score;newNumber();}}
return s;};const average=dir=>{let total=0;for(let i=0;i<RUNS;i++){const s=run(dir);if(s<0)return-1;total+=s;}
return total/RUNS;};let bestScore=0,bestMove=null;for(const dir of names){const s=average(dir);if(s>=bestScore){bestScore=s;bestMove=dir;}}
board=snapshot;return{move:bestMove,score:bestScore};}
return{install,newGame,getData};})(jQuery);